{"check_build": {"code": "script({title:'Wyvern on its Hoard', palette:{rock:{mix:['light bluish grey','dark bluish grey','dark bluish grey']}}});
const G=18;
const Y=r=>G+r;
const mx=(x,w)=>24-x-w;
const GR='dark green', RD='dark red', TN='tan';
const sym=f=>[f(false),f(true)];
const bx=(m,x,r,z,w,h,d,colour,o)=>box(Object.assign({at:[m?mx(x,w):x,Y(r),z],size:[w,h,d],colour:colour},o||{}));
const pl=(m,part,x,r,z,colour,turn,w)=>place({part:part,at:[m?mx(x,w||1):x,Y(r),z],colour:colour,turn:turn||0});

section('Rock',[
 box({at:[-1,0,0],size:[26,6,36],colour:'rock',texture:'masonry'}),
 box({at:[1,6,2],size:[22,6,32],colour:'rock',texture:'masonry'}),
 box({at:[2,12,3],size:[20,6,30],colour:'rock',texture:'masonry'}),
 cylinder({at:[-1,6,28],diameter:2,height:9,colour:'rock'}),
 cylinder({at:[22,6,4],diameter:2,height:12,colour:'rock'}),
 cylinder({at:[0,6,1],diameter:2,height:6,colour:'rock'}),
]);

const legs=m=>[
 bx(m,6,0,7,4,3,6,GR),
 bx(m,7,3,10,2,9,3,GR),
 bx(m,6,0,16,4,3,6,GR),
 bx(m,7,3,19,2,9,3,GR),
 bx(m,6,9,19,3,13,5,GR,{texture:'masonry'}),
 [6,7,8,9].map(x=>pl(m,'54200',x,3,7,TN,0)),
 [6,7,8,9].map(x=>pl(m,'54200',x,3,16,TN,0)),
];
section('Body',[
 box({at:[9,Y(12),10],size:[6,3,14],colour:TN}),
 box({at:[9,Y(15),10],size:[6,9,14],colour:GR,texture:'masonry',top:'tile'}),
 sym(legs),
 [11,12].map(x=>[11,13,15,17,19,21].map(z=>place({part:'54200',at:[x,Y(24),z],colour:RD}))),
]);

const neck=[];
for(let k=0;k<4;k++){
 const z=8-k, r=18+9*k;
 neck.push(box({at:[10,Y(r),z],size:[4,9,4],colour:GR,texture:'masonry'}));
 if(k<3) neck.push(box({at:[11,Y(r),z-1],size:[2,9,1],colour:TN}));
 [11,12].forEach(x=>neck.push(place({part:'4589',at:[x,Y(r+9),z+3],colour:RD})));
}
section('NeckHead',[
 neck,
 box({at:[9,Y(48),0],size:[6,6,8],colour:GR,top:'tile'}),
 box({at:[10,Y(48),-3],size:[4,4,3],colour:GR,top:'tile'}),
 box({at:[10,Y(45),-2],size:[4,3,6],colour:TN}),
 place({part:'3024',at:[10,Y(47),-3],colour:'white'}),
 place({part:'3024',at:[13,Y(47),-3],colour:'white'}),
 place({part:'98138',at:[11,Y(52),-3],colour:'black'}),
 place({part:'98138',at:[12,Y(52),-3],colour:'black'}),
 place({part:'4070',at:[9,Y(51),2],colour:'yellow',turn:90}),
 place({part:'4070',at:[14,Y(51),2],colour:'yellow',turn:270}),
 sym(m=>[
  pl(m,'54200',9,54,1,RD,0),
  pl(m,'3040b',9,54,4,TN,0),
  pl(m,'3062b',9,54,6,TN,0),
  pl(m,'4589',9,57,6,TN,0),
 ]),
]);

const tail=[];
[0,1,2,3].forEach(i=>{
 const z=24+2*i, top=[21,18,15,12][i], w=[4,4,3,3][i];
 tail.push(box({at:[10,Y(0),z],size:[w,top-3,2],colour:GR}));
 for(let x=10;x<10+w;x++) tail.push(place({part:'3040b',at:[x,Y(top-3),z],colour:GR,turn:180}));
});
[0,1,2].forEach(j=>{
 const x=13+2*j, top=[9,6,3][j];
 if(top-3>0) tail.push(box({at:[x,Y(0),29],size:[2,top-3,3],colour:GR}));
 for(let z=29;z<=31;z++) tail.push(place({part:'3040b',at:[x,Y(top-3),z],colour:GR,turn:270}));
});
tail.push(box({at:[19,Y(0),24],size:[2,3,8],colour:GR}));
tail.push(place({part:'3043',at:[19,Y(0),22],colour:RD}));
section('Tail',[tail]);

const L=[9,13,15,12,8];
const wing=m=>{
 const o=[];
 for(let i=0;i<5;i++){
  const xm=6-3*i, ys=22+5*i;
  o.push(bx(m,xm,ys,12,3,6,2,GR,{interior:'solid'}));
  o.push(bx(m,xm,ys,14,1,6,L[i],GR,{interior:'solid'}));
  o.push(pl(m,'4589',xm,ys+6,14+L[i]-1,TN,0));
  if(i<4){
   const lm=Math.min(L[i],L[i+1])-2;
   o.push(bx(m,xm+1,ys+4,14,2,2,lm,RD,{top:'tile'}));
  }
 }
 o.push(pl(m,'4589',-5,48,12,TN,0));
 o.push(pl(m,'4589',-4,48,12,TN,0));
 return o;
};
section('Wings',[sym(wing)]);

section('Hoard',[
 box({at:[4,Y(0),25],size:[5,3,5],colour:'yellow',interior:'solid'}),
 box({at:[5,Y(3),26],size:[3,3,3],colour:'yellow',interior:'solid'}),
 [[4,25],[8,25],[4,29],[8,29],[6,25],[6,29]].map(p=>place({part:'6141',at:[p[0],Y(3),p[1]],colour:'yellow'})),
 place({part:'98138',at:[6,Y(6),27],colour:'yellow'}),
 place({part:'6141',at:[5,Y(6),26],colour:'red'}),
 place({part:'6141',at:[7,Y(6),28],colour:'blue'}),
]);", "seed": 1}}

